#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package Microsoft.Extensions.Caching.StackExchangeRedis@8.0.0 #:package System.Threading.Channels@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using Microsoft.Extensions.Caching.Distributed; using System.Threading.Channels;  var builder = WebApplication.CreateBuilder();  // Redis缓存通道 var cacheChannel = Channel.CreateBounded<CacheOperation>(     new BoundedChannelOptions(10000)     {         SingleReader = true,         AllowSynchronousContinuations = true     });  // 零拷贝缓存处理器 builder.Services.AddSingleton<ICacheHandler>(sp =>      new ChannelCacheHandler(         cacheChannel,         new ThreadLocal<Span<byte>>(() => stackalloc byte[512])));  var app = builder.Build(); app.MapGet("/", () => "Distributed Cache Ready"); app.Run();  [SkipLocalsInit] public class ChannelCacheHandler : ICacheHandler {     [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public unsafe void Handle(in CacheOperation operation)     {         Span<byte> buffer = stackalloc byte[512];         fixed (byte* ptr = buffer)         {             if ((long)ptr % 64 == 0) // Cache-line对齐             {                 // 零拷贝缓存处理             }         }     } }
